# Re-date an OPEN or PENDING claim (a steward). A date after its person's retirement, a claim due
# by a date inside a closed period, or anyone but a steward is refused and writes nothing.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: validate
validate:
  class: net.officefloor.hq.app.claim.ValidateRedate
  govern: [ transaction ]
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: before
# The sheet's figures before the change, so the rollup lines tell which moved.
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: closed
# A claim due by a date inside a closed period is a 409 and writes nothing.
closed:
  class: net.officefloor.hq.app.period.CheckClaimPeriod
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.RedateClaim
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: audit
# Last before the response: every rule has passed and the change is saved.
audit:
  class: net.officefloor.hq.app.claim.AuditClaimRedated
  govern: [ transaction ]
  next: rollup
# After the change's own lines: the figures it moved.
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
# Waive an OPEN or PENDING claim's late charge, once. Anyone but a steward is a 403; a claim in any
# other status, or one already waived, is a 409. A refusal writes nothing.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: apply
# Checks the rules and writes the waiver only when none refuses it.
apply:
  class: net.officefloor.hq.app.claim.WaiveClaim
  govern: [ transaction ]
  next: audit
# Last before the response: every rule has passed and the waiver is saved.
audit:
  class: net.officefloor.hq.app.claim.AuditClaimWaived
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
== src/main/java/net/officefloor/hq/app/role/CheckCanChange.java
package net.officefloor.hq.app.role;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetArchivedException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.web.bind.annotation.PathVariable;

/**
 * Refuses any change by a viewer, and any change at all on an archived sheet, before anything is
 * read or written. A viewer sees every screen and figure and can change nothing; an archived sheet
 * stays visible to everyone and no one can change it. Runs first on every change endpoint except the
 * bulk ones, which go through with every selected item refused.
 */
public class CheckCanChange {
    public void check(@PathVariable("sheetId") String sheetId, RoleRepository roles, SheetRepository sheets,
            HttpServletRequest request) throws ViewerException, SheetArchivedException {
        String id = sheetId == null ? "" : sheetId.trim();
        String user = Audit.user(request);
        if (Role.VIEWER.equals(roles.roleOf(id, user))) {
            throw new ViewerException("A viewer may not change the sheet");
        }
        if (sheets.isArchived(id)) throw new SheetArchivedException(id);
    }
}
== src/main/java/net/officefloor/hq/app/sheet/LoadSheet.java
package net.officefloor.hq.app.sheet;

import jakarta.servlet.http.HttpServletRequest;
import java.time.LocalDate;
import net.officefloor.hq.app.AsOf;
import net.officefloor.hq.app.Preview;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/**
 * Loads the sheet. A read made as of a date (see {@link AsOf}) loads it as it stood at the end of
 * that date, the date standing in for its today; a read made at a preview date (see {@link Preview})
 * loads it as it is now, the preview date standing in for its today. A change always loads it as it
 * is now, at its real today.
 */
public class LoadSheet {
    public void load(@PathVariable("sheetId") String sheetId, SheetRepository repository,
            HttpServletRequest request, Out<Sheet> sheetOut) throws SheetNotFoundException {
        Sheet sheet = repository.find(sheetId == null ? "" : sheetId.trim());
        if (sheet == null) throw new SheetNotFoundException(sheetId);
        boolean read = "GET".equals(request.getMethod());
        LocalDate asOf = read ? AsOf.of(request) : null;
        LocalDate preview = read && asOf == null ? Preview.of(request) : null;
        if (asOf != null) sheetOut.set(repository.asOf(sheet, asOf));
        else if (preview != null) sheetOut.set(new Sheet(sheet.id(), preview, sheet.archived()));
        else sheetOut.set(sheet);
    }
}
