package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.RetiredPersonException;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.role.StewardOnlyException;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Re-dates an OPEN or PENDING claim (a steward). Its new date may not be after its person's
 * retirement. Its due-by and any figure a statement bound it to are kept, and so its period (the one
 * containing its due-by) and its number: a new date inside a closed period is allowed.
 */
public class RedateClaim {
    public void apply(@Val Sheet sheet, @Val Claim claim, @Val Redate redate, PersonRepository people,
            RoleRepository roles, HttpServletRequest request, Out<Redating> redatingOut)
            throws StewardOnlyException, InvalidClaimStatusException, RetiredPersonException {
        redatingOut.set(redate(sheet, claim, redate.date(), people, roles, Audit.user(request)));
    }

    /** Re-dates the claim by the rules above as the user, or refuses and leaves it as it is. */
    static Redating redate(Sheet sheet, Claim claim, LocalDate to, PersonRepository people, RoleRepository roles,
            String user) throws StewardOnlyException, InvalidClaimStatusException, RetiredPersonException {
        if (!Role.STEWARD.equals(roles.roleOf(sheet.id(), user))) {
            throw new StewardOnlyException("Only a steward may re-date a claim");
        }
        if (!claim.isOpen()) {
            throw new InvalidClaimStatusException("A " + claim.getStatus() + " claim cannot be re-dated");
        }
        Person person = people.find(sheet.id(), claim.getPersonId());
        if (person != null && person.retiredBefore(to)) throw new RetiredPersonException(person.getName());

        LocalDate from = claim.getDate();
        claim.setDate(to);
        return new Redating(from, to);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** A re-dating needs the claim's new date. */
public class ValidateRedate {
    public void validate(@RequestBody RedateRequest request, Out<Redate> body) throws InvalidClaimException {
        String raw = request == null || request.date() == null ? "" : request.date().trim();
        try {
            body.set(new Redate(LocalDate.parse(raw)));
        } catch (DateTimeParseException e) {
            throw new InvalidClaimException("A re-dating needs the claim's new date");
        }
    }
}
package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/** Records the re-dating, naming the claim with its new date; the line ends with its old and new dates. */
public class AuditClaimRedated {
    public void audit(@Val Sheet sheet, @Val Claim claim, @Val Redating redating, PersonRepository people,
            HttpServletRequest request, Audit audit) {
        audit.record(ClaimAudit.line("CLAIM_REDATED", sheet, Audit.user(request),
                people.find(sheet.id(), claim.getPersonId()), claim)
                + " old=" + redating.from() + " new=" + redating.to());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.Sheet;

/**
 * A claim's audit record: its person, its amount as the screen shows it, its date, and its number
 * when it has one (a voided claim keeps the number it had).
 */
final class ClaimAudit {
    private ClaimAudit() {}

    static String line(String event, Sheet sheet, String user, Person person, Claim claim) {
        return unnumbered(event, sheet, user, person, claim)
                + (claim.getNumber() == null ? "" : " number=" + claim.getNumber());
    }

    /** The claim's audit record without its number. */
    static String unnumbered(String event, Sheet sheet, String user, Person person, Claim claim) {
        ClaimResponse shown = ClaimResponse.from(claim);
        return event + " sheet=" + sheet.id() + " by=" + user + " person=" + person.getName()
                + " amount=" + shown.amount() + " date=" + shown.date();
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/** Refuses a change to a claim whose due-by (its period) is inside a closed period, before anything is written. */
public class CheckClaimPeriod {
    public void check(@Val Sheet sheet, @Val Claim claim, PeriodRepository periods) throws ClosedPeriodException {
        Period closed = periods.closedOn(sheet.id(), claim.getDueBy());
        if (closed != null) throw new ClosedPeriodException(closed.name());
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A person's claim, as the store holds it. {@code id} is null until first saved. */
public class Claim {
    private Long id;
    private final String sheetId;
    private long personId;
    private BigDecimal amount;
    private LocalDate date;
    private String note;
    private ClaimStatus status;
    private String number;
    private BigDecimal settledDue;
    private String openedBy;
    private String editedBy;
    private boolean stated;
    private BigDecimal statedDue;
    private BigDecimal statedLate;
    private String corrects;
    private LocalDate correctedDate;
    private boolean relisted;
    private LocalDate dueBy;
    private int terms;
    private LocalDate deferredUntil;
    private int proofs;
    private int proofPhotos;
    private String splitFrom;
    private String lockedBy;
    private boolean lateEntry;
    private LocalDate remindedOn;
    private boolean waived;
    private boolean held;
    private String reviewUser;
    private LocalDate reviewOn;
    /** The sheet's today when it last went to PENDING (null: never). */
    private LocalDate pendingOn;
    private String ref;
    private String tags;
    private String voidReason;
    private Integer settleBatch;
    private LocalDate settledOn;

    public Claim(Long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, String number, BigDecimal settledDue,
            String openedBy) {
        this.id = id;
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.status = status;
        this.number = number;
        this.settledDue = settledDue;
        this.openedBy = openedBy;
    }

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public String getSheetId() { return sheetId; }
    public long getPersonId() { return personId; }
    /**
     * Move it to another person: it keeps its date (its new number is given by {@link RenumberClaim}), but loses any figure a statement
     * bound it to (it is live again until its new person's next statement). A SETTLED, VOID or DELETED claim
     * cannot move.
     */
    public void reassign(long toPersonId) throws InvalidClaimStatusException {
        if (status == ClaimStatus.SETTLED || status == ClaimStatus.VOID) {
            throw new InvalidClaimStatusException("A " + status + " claim cannot be moved to another person");
        }
        if (status == ClaimStatus.DELETED) {
            throw new InvalidClaimStatusException("A DELETED claim cannot be moved to another person");
        }
        personId = toPersonId;
        bind(false, null);
        relisted = true;
    }
    /**
     * Move it, whatever its status, with the rest of its person's claims to the person they were merged
     * into: it keeps its number and date, and any figure a statement bound it to, and is listed again.
     */
    public void mergeTo(long toPersonId) {
        personId = toPersonId;
        relisted = true;
    }
    /** Whether it was moved since read, so it is listed again as its new person's newest. */
    public boolean isRelisted() { return relisted; }
    public BigDecimal getAmount() { return amount; }
    public void setAmount(BigDecimal amount) { this.amount = amount; }
    public LocalDate getDate() { return date; }
    public void setDate(LocalDate date) { this.date = date; }
    /** Its due-by, fixed when it was made: the terms-th business day after its date (skipping weekends and the sheet's holidays then), its terms those in force on the day it was made (the sheet's today then): its person's own, else those of the grade they had that day, else the sheet's. Kept when its date changes; fixed again with the same terms when a holiday on or before it is added while it is not SETTLED or VOID. */
    public LocalDate getDueBy() { return dueBy; }
    public void setDueBy(LocalDate dueBy) { this.dueBy = dueBy; }
    /** The terms (business days) its due-by was fixed with. */
    public int getTerms() { return terms; }
    public void setTerms(int terms) { this.terms = terms; }
    /** Fix its due-by: the {@code terms}-th business day after its date, skipping weekends and {@code holidays}. */
    public void fixDueBy(int terms, java.util.Set<LocalDate> holidays) {
        this.terms = terms;
        this.dueBy = net.officefloor.hq.app.holiday.HolidayRepository.businessDaysAfter(date, terms, holidays);
    }
    /** The date it is deferred until; null when it was never deferred. */
    public LocalDate getDeferredUntil() { return deferredUntil; }
    public void setDeferredUntil(LocalDate deferredUntil) { this.deferredUntil = deferredUntil; }
    /**
     * Whether it is deferred on {@code today}: OPEN, and deferred until a date after today. From
     * that date on it is an OPEN claim like any other.
     */
    public boolean isDeferredOn(LocalDate today) {
        return status == ClaimStatus.OPEN && deferredUntil != null && today != null && today.isBefore(deferredUntil);
    }
    /**
     * Defer it until a date after {@code today}: only an OPEN claim may be deferred.
     */
    public void defer(LocalDate until, LocalDate today) throws InvalidClaimStatusException, InvalidClaimException {
        if (status != ClaimStatus.OPEN) {
            throw new InvalidClaimStatusException("A " + status + " claim cannot be deferred");
        }
        if (!until.isAfter(today)) throw new InvalidClaimException("A claim is deferred to a date after today");
        deferredUntil = until;
    }
    /** How many proofs it has had added. */
    public int getProofs() { return proofs; }
    public void setProofs(int proofs) { this.proofs = proofs; }
    /** How many of its proofs are photos. */
    public int getProofPhotos() { return proofPhotos; }

